// microbit - methods
ACMsg.MICROBIT_RESET = "Resets the micro:bit board programmatically, equivalent to pressing the reset button.";
ACMsg.MICROBIT_SLEEP = "Pauses the program for <b>ms</b> milliseconds.";
ACMsg.MICROBIT_RUNNING_TIME = "Returns the time elapsed since the board started, in milliseconds.";
ACMsg.MICROBIT_PANIC = "Displays the error <b>error_code</b> on the LED matrix and resets the board.";
ACMsg.MICROBIT_TEMPERATURE = "Returns the approximate temperature of the board in degrees Celsius.";
ACMsg.MICROBIT_SET_VOLUME = "Sets the global sound volume to the value <b>volume</b> between 0 and 255.";
ACMsg.MICROBIT_WS2812_WRITE = "Writes the contents of the <b>buf</b> buffer to a WS2812 LED strip connected to <b>pin</b>. The buffer must be bytes or bytearray.";
ACMsg.MICROBIT_RUN_EVERY = "Runs the function <b>func</b> every <b>ms</b> milliseconds in the background.";
ACMsg.MICROBIT_SCALE = "Converts <b>value</b> from the range defined by <b>from_low</b> and <b>from_high</b> into a new range defined by <b>to_low</b> and <b>to_high</b>.";
ACMsg.MICROBIT_RUN_EVERY = "Schedule to run a function at the interval specified by the time arguments. Each argument corresponds to a different time unit and they are additive. So <b>run_every(min=1, s=30)</b> schedules the callback every minute and a half. When an exception is thrown inside the callback function it deschedules the function. To avoid this you can catch exceptions with <b>try/except</b>. <b>run_every</b> can also be used as a Decorator, placed on top of the function to schedule.";
ACMsg.MICROBIT_RUN_EVERY_DECORATOR = "Schedules the execution of a function at the interval specified by the time arguments. Each argument corresponds to a different unit of time, and they are added together. Thus, <b>run_every(min=1, s=30)</b> schedules the callback every minute and a half. When an exception is thrown in the callback function, it is held. To avoid this, you can handle exceptions with <b>try/sauf</b>. <b>run_every</b> can also be used as a function, passing the function to be scheduled as the first argument.";
// microbit - display
ACMsg.MICROBIT_DISPLAY = "This module controls the 5x5 LED display on the front of your board. It can be used to display images, animations and even text.";
ACMsg.MICROBIT_DISPLAY_GET_PIXEL = "Return the brightness of the LED at column <b>x</b> and row <b>y</b> as an integer between <b>0</b> (off) and <b>9</b> (bright).";
ACMsg.MICROBIT_DISPLAY_SET_PIXEL = "Set the brightness of the LED at column <b>x</b> and row <b>y</b> to <b>value</b>, which has to be an integer between <b>0</b> and <b>9</b>.";
ACMsg.MICROBIT_DISPLAY_CLEAR = "Set the brightness of all LEDs to <b>0</b> (off).";
ACMsg.MICROBIT_DISPLAY_SHOW = "Display the <b>image</b>.";
ACMsg.MICROBIT_DISPLAY_SHOW_ADVANCED = "If <b>image</b> is a string, float or integer, display letters/digits in sequence. Otherwise, if <b>image</b> is an iterable sequence of images, display these images in sequence. Each letter, digit or image is shown with <b>delay</b> milliseconds between them. If <b>wait</b> is <b>True</b>, this function will block until the animation is finished, otherwise the animation will happen in the background. If <b>loop</b> is <b>True</b>, the animation will repeat forever. If <b>clear</b> is <b>True</b>, the display will be cleared after the iterable has finished. Note that the <b>wait</b>, <b>loop</b> and <b>clear</b> arguments must be specified using their keyword.";
ACMsg.MICROBIT_DISPLAY_SCROLL = "Scrolls <b>text</b> horizontally on the display. If <b>text</b> is an integer or float it is first converted to a string using <b>str()</b>. The <b>delay</b> parameter controls how fast the text is scrolling. If <b>wait</b> is <b>True</b>, this function will block until the animation is finished, otherwise the animation will happen in the background. If <b>loop</b> is <b>True</b>, the animation will repeat forever. If <b>monospace</b> is <b>True</b>, the characters will all take up <b>5</b> pixel-columns in width, otherwise there will be exactly <b>1</b> blank pixel-column between each character as they scroll. Note that the <b>wait</b>, <b>loop</b> and <b>monospace</b> arguments must be specified using their keyword.";
ACMsg.MICROBIT_DISPLAY_ON = "Use <b>on()</b> to turn on the display.";
ACMsg.MICROBIT_DISPLAY_OFF = "Use <b>off()</b> to turn off the display (thus allowing you to re-use the GPIO pins associated with the display for other purposes).";
ACMsg.MICROBIT_DISPLAY_IS_ON = "Returns <b>True</b> if the display is on, otherwise returns <b>False</b>.";
ACMsg.MICROBIT_DISPLAY_READ_LIGHT_LEVEL = "Use the display's LEDs in reverse-bias mode to sense the amount of light falling on the display. Returns an integer between <b>0</b> and <b>255</b> representing the light level, with larger meaning more light.";
// microbit - Image
ACMsg.MICROBIT_IMAGE = "The <b>Image</b> class is used to create images that can be displayed easily on the device's LED matrix. Given an image object it's possible to display it via the <b>display</b> API."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_STR = "If <b>string</b> is used, the string must consist of digits from 0 to 9 arranged in rows, describing the image, for example: <pre>\n\nimage = Image('09090:'\n\t '99999:'\n\t '99999:'\n\t '09990:'\n\t '00900:')\n</pre> will create a 5x5 image of an X. The end of a row is indicated by a colon."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_BUF = "This method creates an empty image with <b>width</b> columns and <b>height</b> rows. The <b>buffer</b> parameter can be an array of size <b>width</b> * <b>height</b> containing integers from 0 to 0. For example: <pre>\n\nImage(2, 2, b'\\x08\\x08\\x08\\x08')\nou\nImage(2, 2, bytearray([9,9,9,9]))\n\n</pre>create an image 2x2 brightness 9.";
ACMsg.MICROBIT_IMAGE_BUILTIN_SEQ = "Built-in sequence of images (animation), for example <b>Image.ALL_CLOCKS</b> or <b>Image.ALL_ARROWS</b>.";
ACMsg.MICROBIT_IMAGE_HEIGHT = "Returns the image height (number of rows).";
ACMsg.MICROBIT_IMAGE_WIDTH = "Returns the image width (number of columns).";
ACMsg.MICROBIT_IMAGE_COPY = "Returns a copy of the image.";
ACMsg.MICROBIT_IMAGE_INVERT = "Returns a new image with pixel brightness inverted.";
ACMsg.MICROBIT_IMAGE_GET_PIXEL = "Returns the brightness at column <b>x</b> and row <b>y</b> as an integer from <b>0</b> to <b>9</b>.";
ACMsg.MICROBIT_IMAGE_SET_PIXEL = "Sets the brightness at column <b>x</b> and row <b>y</b> to <b>value</b> (an integer from <b>0</b> to <b>9</b>).";
ACMsg.MICROBIT_IMAGE_FILL = "Sets all pixels to <b>value</b> (an integer from <b>0</b> to <b>9</b>).";
ACMsg.MICROBIT_IMAGE_SHIFT_LEFT = "Returns a new image shifted left by <b>n</b> columns.";
ACMsg.MICROBIT_IMAGE_SHIFT_RIGHT = "Returns a new image shifted right by <b>n</b> columns.";
ACMsg.MICROBIT_IMAGE_SHIFT_UP = "Returns a new image shifted up by <b>n</b> rows.";
ACMsg.MICROBIT_IMAGE_SHIFT_DOWN = "Returns a new image shifted down by <b>n</b> rows.";
ACMsg.MICROBIT_IMAGE_CROP = "Returns a new image cropped from the rectangle starting at <b>x</b>, <b>y</b> with size <b>w</b> x <b>h</b>.";
ACMsg.MICROBIT_IMAGE_BLIT = "Copies a rectangle from <b>src</b> into this image (blit).";
